// Generated by gbaa-lift (crates/codegen/src/native/pc_marks_build.rs).
// Don't edit; rerun `just lift`.
//
// Each lifted block's guest pc, for a stop to name (unit
// `native/lift-pc-markers`): src/ has no marker lines, so a reader meets
// none; pcs.txt keeps where each block starts. In a build with the
// `guest-pc` feature this script writes each module of src/ to OUT_DIR
// with `pc(0x…);` put back at its blocks, and main.rs's `lifted_mod!`
// builds that copy. A module whose text isn't the one pcs.txt was made
// from (edited by hand) is copied as it is, with a warning: its stops
// name no block.

use std::path::Path;

/// pcs.txt, the side table.
pub const TABLE: &str = "pcs.txt";

/// Where a block's `pc` goes in its module's text, the line counted in
/// the text without markers (0 the first).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Mark {
    pub line: usize,
    pub key: u32,
    /// `Some(n)`: a line of its own before `line`, `n` spaces in; `None`:
    /// at the end of `line`, a `match` arm's `N => {` (written `arm`).
    pub indent: Option<usize>,
}

/// FNV-1a, 64 bits: which text a module's marks were taken from.
pub fn fnv(text: &str) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for b in text.bytes() {
        h ^= u64::from(b);
        h = h.wrapping_mul(0x0000_0100_0000_01b3);
    }
    h
}

/// The table's modules: each file's name, its text's hash and its marks.
pub fn parse(table: &str) -> Result<Vec<(String, u64, Vec<Mark>)>, String> {
    let mut out: Vec<(String, u64, Vec<Mark>)> = Vec::new();
    for (n, l) in table.lines().enumerate() {
        let bad = || format!("{TABLE}:{}: {l:?}", n + 1);
        let w: Vec<&str> = l.split_whitespace().collect();
        match w.as_slice() {
            [] => {}
            [c, ..] if c.starts_with('#') => {}
            ["file", f, h] => {
                let h = u64::from_str_radix(h, 16).map_err(|_| bad())?;
                out.push((f.to_string(), h, Vec::new()));
            }
            [line, key, how] => {
                let line = line.parse().map_err(|_| bad())?;
                let key = u32::from_str_radix(key, 16).map_err(|_| bad())?;
                let indent = match *how {
                    "arm" => None,
                    i => Some(i.parse().map_err(|_| bad())?),
                };
                let (_, _, m) = out.last_mut().ok_or_else(bad)?;
                m.push(Mark { line, key, indent });
            }
            _ => return Err(bad()),
        }
    }
    Ok(out)
}

/// `text` with its marks put back: the text as the lifter printed it.
pub fn restore(text: &str, marks: &[Mark]) -> String {
    let mut out = String::with_capacity(text.len() + marks.len() * 24);
    let mut m = marks.iter().peekable();
    let mut before = |out: &mut String, i: usize, arm: bool| {
        while let Some(k) = m.next_if(|k| k.line == i && (k.indent.is_some() || arm)) {
            match k.indent {
                Some(n) => {
                    out.extend(std::iter::repeat_n(' ', n));
                    out.push_str(&format!("pc({:#010x});\n", k.key));
                }
                None => out.push_str(&format!(" pc({:#010x});", k.key)),
            }
        }
    };
    let mut lines = 0;
    for (i, l) in text.split_inclusive('\n').enumerate() {
        before(&mut out, i, false);
        let body = l.strip_suffix('\n');
        out.push_str(body.unwrap_or(l));
        before(&mut out, i, true);
        if body.is_some() {
            out.push('\n');
        }
        lines = i + 1;
    }
    before(&mut out, lines, false);
    out
}

#[allow(dead_code)]
fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed={TABLE}");
    if std::env::var_os("CARGO_FEATURE_GUEST_PC").is_none() {
        return;
    }
    let dir = std::env::var("CARGO_MANIFEST_DIR").expect("cargo sets it");
    let out = std::env::var("OUT_DIR").expect("cargo sets it");
    let dir = Path::new(&dir);
    let table = std::fs::read_to_string(dir.join(TABLE))
        .unwrap_or_else(|e| panic!("{TABLE}: {e} (rerun `just lift`)"));
    for (f, h, marks) in parse(&table).unwrap_or_else(|e| panic!("{e}")) {
        let src = dir.join("src").join(&f);
        println!("cargo:rerun-if-changed={}", src.display());
        let text =
            std::fs::read_to_string(&src).unwrap_or_else(|e| panic!("{}: {e}", src.display()));
        let put = if fnv(&text) == h {
            restore(&text, &marks)
        } else {
            println!(
                "cargo:warning=src/{f} isn't the text {TABLE} was made from: its stops name no block"
            );
            text
        };
        let to = Path::new(&out).join(&f);
        if std::fs::read_to_string(&to).ok().as_deref() != Some(put.as_str()) {
            std::fs::write(&to, put).unwrap_or_else(|e| panic!("{}: {e}", to.display()));
        }
    }
}
